import json, os, sys
sys.path.insert(0, "/app/src")
from metalquant import reduce_batch

base = {
  "analytes": [{"name": "Pb", "mdl": 0.05, "loq": 0.2}],
  "standards": [
    {"conc": {"Pb": 0.0}, "counts": {"Pb": 310.0}, "is_counts": 51200.0},
    {"conc": {"Pb": 1.0}, "counts": {"Pb": 9120.0}, "is_counts": 50880.0},
    {"conc": {"Pb": 10.0}, "counts": {"Pb": 88750.0}, "is_counts": 50410.0},
  ],
}

def b(runs):
    d = dict(base); d["runs"] = runs
    return reduce_batch(d)

S = lambda i, c, dil=1: {"id": i, "kind": "sample", "counts": {"Pb": c}, "is_counts": 50000.0, "dilution": dil}
B = lambda i, c: {"id": i, "kind": "blank", "counts": {"Pb": c}, "is_counts": 50000.0}
C = lambda i, c: {"id": i, "kind": "ccv", "counts": {"Pb": c}, "is_counts": 50000.0, "true": {"Pb": 10.0}}
P = lambda i, par, c, add=20.0, dil=1: {"id": i, "kind": "spike", "parent": par, "added": {"Pb": add}, "counts": {"Pb": c}, "is_counts": 50000.0, "dilution": dil}

cases = {
 "no blanks, no ccvs": [S("A", 20000.0)],
 "blanks all ND": [B("MB", 100.0), S("A", 20000.0)],
 "several blanks mixed": [B("MB1", 100.0), S("A", 20000.0), B("MB2", 2000.0), B("MB3", 3000.0)],
 "negative reading": [S("A", 0.0)],
 "sample before first ccv": [S("A", 20000.0), C("C1", 40000.0)],
 "sample after last ccv": [C("C1", 88000.0), S("A", 20000.0)],
 "bracketed fail": [C("C1", 88000.0), S("A", 20000.0), C("C2", 40000.0)],
 "spike with ND parent": [S("A", 300.0), P("AS", "A", 100000.0)],
 "dilution 1000": [S("A", 20000.0, 1000), P("AS", "A", 60000.0, 1000.0, 1000)],
}
for name, runs in cases.items():
    try:
        print(name, "->", json.dumps(b(runs)))
    except Exception as exc:
        print(name, "!! ", type(exc).__name__, exc)
